ALTER TABLE users ADD COLUMN avatar_url TEXT NOT NULL DEFAULT '';
ALTER TABLE files ADD COLUMN uploader_user_id TEXT REFERENCES users(id);
ALTER TABLE uploads ADD COLUMN uploader_user_id TEXT REFERENCES users(id);
ALTER TABLE uploads ADD COLUMN completing INTEGER NOT NULL DEFAULT 0;
UPDATE files SET uploader_user_id=(SELECT c.owner_user_id FROM themes t JOIN cabinets c ON c.id=t.cabinet_id WHERE t.id=files.theme_id);
UPDATE uploads SET uploader_user_id=(SELECT owner_user_id FROM cabinets WHERE id=uploads.cabinet_id);
CREATE INDEX files_uploader ON files(uploader_user_id);
CREATE INDEX uploads_uploader ON uploads(uploader_user_id);
ALTER TABLE site_settings ADD COLUMN hero_title TEXT NOT NULL DEFAULT '把美好，收进同一个柜子。';
ALTER TABLE site_settings ADD COLUMN hero_description TEXT NOT NULL DEFAULT '整理照片、收藏文件，用一个链接连接彼此。';
ALTER TABLE site_settings ADD COLUMN hero_background TEXT NOT NULL DEFAULT '';
CREATE TABLE workbench_owner (id INTEGER PRIMARY KEY CHECK(id=1), user_id TEXT NOT NULL UNIQUE REFERENCES users(id));
INSERT INTO workbench_owner(id,user_id) SELECT 1,id FROM users WHERE username='chenhuichuangChc2324';
CREATE TABLE workbench_profile (user_id TEXT PRIMARY KEY REFERENCES users(id), introduction TEXT NOT NULL DEFAULT '');
CREATE TABLE workbench_tasks (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', due_date TEXT NOT NULL DEFAULT '', criteria TEXT NOT NULL DEFAULT '', progress INTEGER NOT NULL DEFAULT 0, sort_order INTEGER NOT NULL DEFAULT 0, focus INTEGER NOT NULL DEFAULT 0, poster TEXT NOT NULL DEFAULT '', celebration INTEGER NOT NULL DEFAULT 0, seen INTEGER NOT NULL DEFAULT 0);
CREATE INDEX workbench_tasks_user ON workbench_tasks(user_id);
CREATE TABLE word_libraries (id TEXT PRIMARY KEY, category_id TEXT NOT NULL REFERENCES word_categories(id), uploader_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'importing', total INTEGER NOT NULL DEFAULT 0, imported INTEGER NOT NULL DEFAULT 0, error TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE word_library_entries (library_id TEXT NOT NULL REFERENCES word_libraries(id), position INTEGER NOT NULL, english TEXT NOT NULL, chinese TEXT NOT NULL, PRIMARY KEY(library_id,position));
CREATE TABLE word_schedules (id TEXT PRIMARY KEY, library_id TEXT NOT NULL UNIQUE REFERENCES word_libraries(id), start_date TEXT NOT NULL, publish_time TEXT NOT NULL, daily_count INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL);
CREATE TABLE word_schedule_runs (id TEXT PRIMARY KEY, schedule_id TEXT NOT NULL REFERENCES word_schedules(id), study_date TEXT NOT NULL, batch_id TEXT NOT NULL, count INTEGER NOT NULL, created_at TEXT NOT NULL, UNIQUE(schedule_id,study_date));
